import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), l = nextInt(), r = nextInt();
        int answer = 0;
        for (int i = 0; i <= r; i++) {
            skip();
            int s = pos;
            while (pos < buf.length && buf[pos] > ' ') pos++;
            if (i < l) continue;
            int mask = 0;
            boolean valid = true;
            for (int k = s; k < pos; k++) {
                int bit = 1 << (buf[k] - '0');
                if ((mask & bit) != 0) {
                    valid = false;
                    break;
                }
                mask |= bit;
            }
            if (valid) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	nextInt()
	l, r := int(nextInt()), int(nextInt())
	answer := 0
	for i := 0; i <= r; i++ {
		tok := next()
		if i < l {
			continue
		}
		mask, valid := 0, true
		for _, c := range tok {
			bit := 1 << (c - '0')
			if mask&bit != 0 {
				valid = false
				break
			}
			mask |= bit
		}
		if valid {
			answer++
		}
	}
	fmt.Println(answer)
}
